    "text": "答：适合的场景通常具备三个特征：客户需要培养\nAI\n或智能体应用开发人才；客户需要可操作、可演示、可验收的实训平台；客户愿意围绕课程、项目、模型、数据或业务场景进行持续运营。若客户只需要一次性讲座、纯视频课程或单个工具试用，平台价值不容易完整体现，可先以课程或\nPOC\n切入，再逐步引导到平台化建设。 售前判断时应重点询问：使用对象是谁、培训目标是什么、是否需要学生或员工实际完成项目、是否需要后台管理和考核、是否有私有化部署和数据安全要求、是否需要对外展示或验收。答案越明确，越适合推进平台方案。"
