    "text": "图\n 3-4 \n项目创建向导\n图\n 3-5 \n项目实例列表\n数据资源与模型实训\n平台提供数据广场和我的数据两类数据资源入口。数据广场集中展示平台共享数据集，数据集卡片可呈现名称、标签、简介和适用方向，用户可根\n据训练、评测或项目实训需要选择合适数据；我的数据用于查看当前账号创建、导入或被授权使用的数据资源，展示数据来源、状态和可用操作，帮助用户在提交训练或评测任务前确认数据可用性。"
