    "text": "图\n 3-10 \n智能体广场\n图\n 3-11 \n我的智能体\n个人空间与个人中心\n个人空间聚合用户自有工具和知识资源，包括\nMCP\n工具、知识库和插件管理。学员或教师在开展智能体编排、\nRAG\n应用、项目实训或工具调用前，可在个人空间确认可调用能力是否已准备完成，并按类型、状态和关键字筛选\nMCP\n服务，查看知识库和插件资源。 个人中心用于维护账号资料、\nAPI-Key\n和密码等个人信息。用户可在个人主页查看账号基础信息，在资料设置中维护个人资料，在\nAPI-Key\n页面查\n看、创建、编辑或删除接口调用凭证，并在修改密码页面完成密码更新。由于\nAPI-Key\n、密码和模型服务凭证属于敏感信息，平台在操作和文档层面均强调不展示明文密钥或真实密码。"
