    "text": "图\n 3-12 MCP \n工具列表\n图\n 3-13 \n知识库\n图\n 3-14 API-Key \n管理\n后台管理与运营支撑\n后台管理面向管理员和运营人员，主要用于用户、课程、考核、资源、运维、智能体和系统配置管理。后台系统首页可集中展示场景信息、课程资源、训练资源、能力考核资源和浏览节点状态，帮助管理员快速了解平台运行与资源概况。用户管理覆盖账号、组织、班级和群组维护，支撑院校班级教学、企业培训分组和资源权限分配。"
