    "text": "数据\n知识可检索、数据可授权、来源可确认、使用可审计。 工程\n应用可集成、可测试、可回归、可维护并稳定运行。 治理\n权限可控、结果可核验、风险有门槛、责任有归属。 运营\n持续监测使用、效果、成本与反馈，推动迭代和复制。 评价焦点已改变：业务愿意用、流程接得住、结果能核验、数据与权限可控、投入能够持续。 01\n02\n缺一不可\n01\n02\n03\n04\n05\n06\n--- 第4页 ---"
