    "text": "--- 第1页 ---\n实网攻防中心\n360智能体应用开发\n实训平台产品介绍\n--- 第2页 ---\n智能体时代：人才趋势与岗位新机遇\n--- 第3页 ---\n建设必要性与价值目标\n--- 第4页 ---\n典型使用场景：赋能AI教学实训\n--- 第5页 ---\n平台关键技术与能力\n--- 第6页 ---\n智能体演进方向和等级划分\n只需业务⼈员提出⽬标或任务意图即可进行逻辑推演调用工具完成目标；\n代表如 Manus 、AutoGen等；典型应用:深度研究，做海报，做网页\n按照人类组织分工、协同的逻辑，像搭建团队一样组合不同智能体完成高复杂任务；典型应用长视频、做网站等创造性工作。"
