    "text": "挑战\n高度依赖提示词，有门槛且行为稳定性不足，结果难以预测；\n很容易出现“幻觉”⽽不可信，连续小的错误积累了可导致任务失败\n需具备\n需要有多智能体的协同、多类别的兼容能力；\n需具备跨智能的上下文关系与协同，避免上下文信息的污染能力；\n具备人在回路、自动修复，超长任务的连续执行和复杂任务的不出错能力\nL4级\nL3级\n低代码的智能体执行严谨，适用于简单重复的工作，结果准确；\n 典型应用知识库问答、电商客服助手\n挑战\n门槛高，面向的是有开发基础的人 ；\n缺乏智能化的任务理解与适配能⼒，一旦业务流程变化，需要重构流程和分支逻辑。"
