    "text": "--- 第8页 ---\n360智能体应用开发实训平台 产品功能全景\n一站式智能体应用构建开发、学习实训中心\n基于智能体课程、项目实例、智能体平台等进行持续赋能\n真\n实\n场\n景\n智\n能\n体\n搭\n建\n人\n才\n培\n养\n及\n能\n力\n提\n升\n课程大纲\n实操构建\n讲义/视频\n课后习题\n实操指导\n目标制定\n任务下发\n课程学习\n智能体实操\n效果评测\n智能体使用\n项目实例\nL3推理智能体\nL4智能体蜂群\nGUI智能应用\n异构智能体纳管\n智能体工厂\nL2工作流编排\n内置工具丨MCP生态｜外挂知识库｜记忆增强\n--- 第9页 ---\n智能体开发全流程覆盖\n--- 第10页 ---\n低代码编排与工作流实践\n通过可视化拖拽式编排，快速组合模型、知识与工具，构建业务流程，完成应用原型。\n--- 第11页 ---"
