    "text": "通过平台建设，客户能够在本地或专有环境中形成智能体应用开发实训底座，支撑院校课程升级、职业院校实训基地建设、企业内部\nAI\n人才培养和区域人工智能人才公共服务能力建设。 产品目标\n360\n智能体应用开发实训平台的目标，是帮助客户建立一套围绕智能体应用开发全过程的人才培养体系，使课程内容、实践环境、项目任务、能力评价和成果沉淀形成闭环。平台重点解决课程更新慢、实践环境不足、资源分散、工程能力培养不充分、教学过程难评价和安全治理要求提升等问题。"
