    "text": "课程体系建设\n平台支持围绕大模型基础、提示词工程、\nRAG\n系统、智能体开发、\nMCP\n工具开发、多智能体协同、\nGUI\n智能应用、模型训练评测和项目综合实训等方向组织课程资源。教师可根据专业培养目标或培训计划配置课程路径，使学员从基础认知逐步过渡到工程化实践。 项目化实训\n平台以项目实例和实训任务承载实践训练。学员可围绕教学助手、企业知识助手、招投标文档助手、合同审核助手、简历筛选助手、会议纪要助手、数据分析助手等场景开展训练，完整经历需求理解、知识准备、工具接入、智能体构建、效果验证和成果提交。"
