    "text": "图\n 2-1 360\n智能体应用开发实训平台架构示意图\n从用户入口看，平台前台面向学员、教师和实训参与者，提供\nAI\n课堂、项目实例、数\n据广场、模型空间、模型训练评测、智能体中心、个人空间和个人中心等功能；后台面向管理员和运营人员，提供用户管理、课程资源、能力考核、资源管理、运维管理、智能体管理和系统管理能力。 从能力层看，平台将模型服务、知识库、\nMCP\n工具、数据集、智能体构建、训练评测和运营管理整合到统一环境中。底层能力服务于课程和项目，而不是分散暴露为多个独立系统，使教学和培训活动能够按统一流程组织，训练过程能够被记录、评价和复用。"
