    "text": "核心功能\n平台核心功能围绕智能体应用开发实训全过程展开，覆盖课程学习、项目实训、数据与模型、智能体构建、知识库与\nMCP\n工具、能力考核和后台运营管理等环节。各模块既可以独立支撑单项教学活动，也可以组合形成完整的\n“\n学、练、测、评、用、沉淀\n”\n培养闭环。 AI\n课堂与课程学习\nAI\n课堂是平台承载课程学习的核心入口，支持课程列表、课程筛选、课程详情、课程目录和课时学习。教师可围绕课程方向、课程难度、适用对象、课程收益和前置知识组织课程内容，学员可按学习阶段进入课程，查看实验背景、实验目的、实验环境、实验原理和操作要求。"
