    "text": "数据资源与模型实训\n平台提供数据广场和我的数据两类入口，用于集中管理训练、评测和项目所需的数据资源。学员可根据项目任务选择合适数据集，教师和管理员可维护共享数据、项目数据和组织内部数据，保证训练材料可控、可追踪、可复用。 模型实训能力覆盖模型空间、模型体验、模型部署、模型训练和模型评测。学员可以在授权范围内体验不同模型，理解模型能力差异；也可以围绕训练任务和评测任务完成数据选择、模型选择、训练方法配置、资源规格选择和评测结果分析，形成对模型能力和智能体效果关系的完整认识。"
