    "text": "MCP\n工具能力用于连接外部能力，使智能体从内容生成扩展到任务执行。平台支持文件、图像、音频、视频、图表、数据库等多类型工具能力，并支持通过\nOpenAPI\n协议文档将私域\nAPI\n转化为可调用工具。该能力适合教学项目和企业培训围绕真实系统能力设计任务。 知识库与工具资源还承担案例复用和组织资产沉淀作用。教师和管理员可以将成熟项目中的知识库、提示词、工具配置和智能体模板保存为可复用资源，支撑后续课程、实训和培训批次快速开展。 能力考核与评测画像\n平台支持课程考核、题库试卷、实训任务评价、模型评测和智能体成果评价。传统考试只能反映理论掌握情况，而智能体应用开发能力更需要结合项目过程、工具调用、知识库应用、结果质量和调优能力进行综合判断。"
