    "text": "通过学习记录、项目进度、作业提交、模型评测、智能体运行、成果采纳和教师评价等数据，平台可以形成学员能力画像。能力画像可用于课程结课评价、实训基地验收、认证培养、企业内部人才盘点和岗位匹配，帮助组织将培养结果转化为可识别的人才数据。 后台管理与运营支撑\n后台管理面向管理员和运营人员，提供用户管理、课程资源管理、能力考核管理、资源管理、运维管理、智能体管理和系统配置能力。管理员可以统一维护组织账号、班级群组、课程内容、题库试卷、模型数据集、知识库、\nMCP\n工具、智能体分类和模板。 智能体运营管理支持智能体审核、分类、精选、上下架和模板沉淀。该能力既能控制前台展示质量，也能保障课程成果、项目成果和企业内部智能体资源在授权范围内流转，避免未审核内容随意扩散。"
