    "text": "高校在智能体人才培养面临的问题\n除人工智能及计算机相关专业外，大部分专业课程体系中 缺乏AI工具与智能体应用相关内容，学生难以系统掌握AI辅助工作的能力。 虽然很多学生会使用部分AI工具，但 缺乏系统训练与方法指导，难以在学习、研究和未来工作中高效应用智能体。 高校普遍缺乏 面向全校专业开放的AI实践与实训环境，学生难以结合本专业场景开展智能体应用实践。 越来越多企业岗位开始要求具备 AI工具与智能体应用能力，而高校在通用AI能力培养方面尚未形成成熟体系。 多数专业缺乏\nAI智能体应用课程\n学生AI应用\n能力参差不齐\n缺少跨专业的\nAI实践平台\n人才培养与企业\n岗位需求存在差距\n随着智能体技术快速发展，高校在课程体系、实践环境与产业对接等方面仍存在明显短板，难以满足产业对智能体工程人才的需求。"
