    "text": "--- 第7页 ---\n360 智能体工程师认证\n关键问题\n构建产业级能力标准\n360数字安全集团发布的智能体工程师标准及认证体系，智能体开发方向分为智能体工程师（ADEA）、智能体高级工程师（ADEP）和智能体专家（ADEE）三级，AI应用方向为360AI应用工程师，聚焦技术与业务能力培养，解决AI时代复合型人才短缺，支撑智能体产业落地。\n能力无法被量化，价值无法被证明\n复合型人才稀缺\n重建\n标准\n发布智能体工程师能力标准\n构建三级阶梯认证体系\n一考双证，增强行业公信力\n统一能力度量体系\n重塑\n能力\n打通产教与产业落地\n融合 AI + 安全 实战经验\n培养复合型人才\n打造系统级工程人才\n--- 第8页 ---"
