    "text": "一考双证：企业技术证书 + NITE项目证书\n360创新实施“一考双证”的人才评价体系——实现大厂技术认可与国家官方背书的双重权威保障。同时，认证已纳入国家软件与集成电路公共服务平台信息技术紧缺人才培养工程（简称NITE）。\nNITE项目，定位于培养国家战略性新兴产业和国家重点领域信息技术紧缺人才。该项目于2006年启动，现由中国电子工业科学技术交流中心有限公司负责运营和管理，证书由中国软件评测中心（工业和信息化部软件与集成电路促进中心）核发。\n--- 第12页 ---\n360微认证AI应用师证书样本\n颁证单位：360数字安全集团\n--- 第13页 ---\n360ADE证书+NITE项目证书样本\n颁证单位：360数字安全集团/工业和信息化部软件与集成电路促进中心\n--- 第14页 ---"
