    "text": "360 AI+学院解决方案-AI+人才培养中心\nAI+人才培养中心\n建设方向\n落地产品\n创新实训室建设\n网络安全教学实训室\n人工智能教学实训室\n智能体工厂实训室\n人才培养内涵建设\n网安专业课程建设\n人工智能通识/专业课程建设\n研究课题承接和申报\n微专业/订单班/特色班定制\n工程实践体系建设\n产业实习实践服务\n攻防实战靶场建设\n网安竞赛培训/组织营服务\n社会项目引入和项目承接\n师资培训服务\n双师型教师队伍建设\n师资工作站（寒暑假）\n企业认证\n产业学术报告\n师资培养体系建设\n课程平台\n课程建设\n靶场/竞赛平台\n师资服务\n项目规模\n根据学校的专业建设需求，建设可用于网安/人工智能专业日常教学用实训室，可包含教学平台、竞赛平台、靶场平台、智能体应用创新平台等，同时可打包整个实训室的学习工位、装修、及文化墙设计。"
