    "text": "360 AI+学院解决方案-认证培训中心\n智能体工程师（ADEA，Agent Deployed Engineer Expert）：面向智能体工程初学者，重点考察对智能体基础概念、基本架构和单一场景智能体构建能力的掌握情况。\n 智能体高级工程师（ADEP，Agent Deployed Engineer Professional）：面向具备一定实践经验的工程人员，重点评估其在多工具、多流程场景下构建稳定智能体系统的能力，以及与业务系统集成的工程能力。\n 智能体专家（ADEE，Agent Deployed Engineer Associate）：面向承担企业级智能体系统设计与落地的核心人员，重点考察复杂场景下的系统架构能力、多智能体协同设计能力以及智能体系统的长期运营与优化能力。"
