    "text": "360流量安全产品典型应用场景\n01 APT攻击、未知威胁检测\n场景需求：\n高价值事件发现、APT挖掘\n威胁狩猎、取证和响应、安全运营\n方案：\n部署NDR运用威胁情报、流量分析、机器学习、沙箱检测、加密流量检测等技术，实现专业化、精准化、智能化检测\n价值：\n集中监测、预警APT；形成更持续有效的监管机制\n02 加密流量识别和检测\n场景需求：\n加密流量威胁影响范围不可知\n没有应对加密流量攻击行为的检测机制\n方案：\n通过加密流量威胁情报快速识别已知加密流量攻击行为\nAI不解密加密模型，识别加密流量协议，加密远控流量、异常SSL通信行为、APT家族伪装检测等\n价值：\n高效识别恶意加密流量威胁\n03 热点威胁监测（勒索/挖矿）\n场景需求：\n勒索/挖矿种类多、迭代快\n传统杀软无法及时查杀、难以防范\n方案：\n部署NDR通过协议特征、异常行为、诱捕技术快速识别勒索、挖矿病毒、集中整治、联动处理（EPP、FW）\n价值：\n应急响应、集中整治、避免被通报\n07 合规建设（等保/关基）\n场景需求：\n等保：具有抗APT检测相关组件\n关基：建立风险监测预警机制\n网络安全法：具备威胁检测能力\n方案：\n部署NDR满足等保、关基建设要求\n价值：\n提升等保合规分数，顺利通过测评\n一笔投入两笔收益，合规和安全同步实现\n05 网络侧-数据泄露监测\n场景需求：\n监测数据泄露线索、跨境治理\n方案：\n部署NDR基于流量识别被动网络资产、敏感数据信息、文件泄露问题\n价值：\n及时发现数据泄露，防止政企重大损失。"
